/** Outstanding invitations: not accepted and not revoked, every role. */
export async function countPendingInvitations(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(invitations)
    .where(pendingInvitationPredicate(orgId))
    .get();
  return row?.value ?? 0;
}

/** Pending invitations for a billable role. Viewer invites do not hold a seat. */
export async function countPendingBillableInvitations(
  orgId: OrgId,
): Promise<number> {
  const roles = ROLES.filter((role) => isBillableRole(role));
  const row = getDb()
    .select({ value: count() })
    .from(invitations)
    .where(and(pendingInvitationPredicate(orgId), inArray(invitations.role, roles)))
    .get();
  return row?.value ?? 0;
}

function pendingInvitationPredicate(orgId: OrgId) {
  return and(
    orgPredicate(invitations.orgId, orgId),
    isNull(invitations.acceptedAt),
    isNull(invitations.revokedAt),
  );
}

