/**
 * Promoting an active viewer into a billable role takes one seat, counted the
 * same way invitations count seats. The role row is left untouched when the
 * plan cannot spare it. Moves between billable roles, and any move onto
 * `viewer`, are not seat changes.
 */
async function assertSeatAvailableForPromotion(
  orgId: OrgId,
  member: Member,
  nextRole: Role,
): Promise<void> {
  const takesSeat =
    member.status === "active" &&
    member.archivedAt === null &&
    !isBillableRole(member.role) &&
    isBillableRole(nextRole);
  if (!takesSeat) return;

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  const seatsUsed = await countSeatsInUse(orgId);
  if (!wouldExceedLimit(org.plan, "seats", seatsUsed, 1)) return;

  const limits = getPlanLimits(org.plan);
  throw new Error(
    `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
  );
}

