import * as memberRepo from "@/server/repositories/member-repository";
import * as invitationService from "@/server/services/invitation-service";
import * as memberService from "@/server/services/member-service";

// A full free plan (3 billable members) refuses promoting the viewer, and
// the row is left unchanged. Demoting a billable role does not need a seat.
it("refuses to promote a viewer when the seat quota is full", async () => {
  const tenant = await createTenant("member-viewer-seat", "free");
  const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
  if (!target) throw new Error("fixture member missing");

  await expect(
    memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
      role: "member",
    }),
  ).rejects.toThrow(/seats/);

  await expect(
    memberRepo.findMember(tenant.org.id, tenant.userIds.viewer),
  ).resolves.toMatchObject({ role: "viewer" });

  const billable = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
  if (!billable) throw new Error("fixture member missing");

  const demoted = await memberService.updateMemberRole(tenant.actors.owner, {
    orgId: tenant.org.id,
    memberId: billable.id,
    role: "viewer",
  });
  expect(demoted.role).toBe("viewer");
});

// Pending billable invitations reserve a seat, same as the invite path.
it("counts pending billable invitations when promoting a viewer", async () => {
  const tenant = await createTenant("member-pending-seat", "starter");

  for (let i = 0; i < 7; i += 1) {
    await invitationService.inviteMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      email: `pending${i}@member-pending-seat.test`,
      role: "member",
    });
  }

  const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
  if (!target) throw new Error("fixture member missing");

  await expect(
    memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
      role: "admin",
    }),
  ).rejects.toThrow(/seats/);

  await expect(
    memberRepo.findMember(tenant.org.id, tenant.userIds.viewer),
  ).resolves.toMatchObject({ role: "viewer" });

  const adminMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
  if (!adminMember) throw new Error("fixture member missing");

  const moved = await memberService.updateMemberRole(tenant.actors.owner, {
    orgId: tenant.org.id,
    memberId: adminMember.id,
    role: "member",
  });
  expect(moved.role).toBe("member");
});

