input.new_string:
  it("leaves an org with room under its limit", async () => {
    await usageService.recomputeUsage(growth.org.id);

    const check = await billingService.checkLimit(growth.org.id, "seats");
    expect(check.exceeded).toBe(false);
    expect(check.remaining).toBeGreaterThan(0);
  });

  it("keeps incremental seat adjustments equal to a full recount", async () => {
    const tenant = await createTenant("seat-counter", "growth");
    const detach = usageService.registerUsageListeners();

    try {
      await usageService.recomputeUsage(tenant.org.id);
      expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(3);

      const viewer = await userRepo.insertUser({
        email: "extra-viewer@seat-counter.test",
        name: "Extra Viewer",
        passwordHash: "seed",
      });
      const viewerMember = await memberRepo.insertMember(
        tenant.org.id,
        viewer.id,
        "viewer",
        null,
      );
      await emit("member.joined", {
        orgId: tenant.org.id,
        actorId: tenant.userIds.owner,
        occurredAt: toIsoTimestamp(new Date()),
        memberId: viewerMember.id,
        userId: viewer.id,
        role: "viewer",
      });
      expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(3);

      const person = await userRepo.insertUser({
        email: "extra-member@seat-counter.test",
        name: "Extra Member",
        passwordHash: "seed",
      });
      const personMember = await memberRepo.insertMember(
        tenant.org.id,
        person.id,
        "member",
        null,
      );
      await emit("member.joined", {
        orgId: tenant.org.id,
        actorId: tenant.userIds.owner,
        occurredAt: toIsoTimestamp(new Date()),
        memberId: personMember.id,
        userId: person.id,
        role: "member",
      });
      expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(4);

      await memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: personMember.id,
        role: "viewer",
      });
      expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(3);

      await memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: personMember.id,
        role: "member",
      });
      expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(4);

      await memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: personMember.id,
      });
      expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(3);

      await memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewerMember.id,
      });
      expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(3);

      const recounted = await usageService.recomputeUsage(tenant.org.id);
      expect(recounted.seatsUsed).toBe(3);
      expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(
        recounted.seatsUsed,
      );
    } finally {
      detach();
    }
  });
});

